import json
demos=json.load(open('programs/task-1aba4c20.json'))

def shapes_of(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                q=[(i,j)]; seen.add((i,j)); cells=[]
                while q:
                    y,x=q.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<h and 0<=b<w and g[a][b] and (a,b) not in seen:
                            seen.add((a,b)); q.append((a,b))
                out.append(cells)
    return out

def orient(cells):
    rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
    # bar = the row or col with 3 cells
    from collections import Counter
    rc=Counter(r for r,c in cells); cc=Counter(c for r,c in cells)
    if max(rc.values())==3: return 'down' if min(rs)==min(r for r,n in rc.items() if n==3) else 'up'
    return 'right' if min(cs)==min(c for c,n in cc.items() if n==3) else 'left'

SLOTS=[(0,0),(0,2),(2,0),(2,2)]
def transform(g):
    ss=shapes_of(g)
    ups=[s for s in ss if orient(s)=='up']; downs=[s for s in ss if orient(s)=='down']
    o=[[0]*6 for _ in range(3)]
    for k in range(len(ups)):
        i,j=SLOTS[k]; o[i][j]=3
    for k in range(len(downs)):
        i,j=SLOTS[k]; o[i][3+j]=1
    return o

